 <div class="home-kpis"><button data-launch="sales"><span class="kpi-icon blue">${icon('target')}</span><span><small>Open pipeline</small><b>${money(state.deals.filter(d=>d.stage!=='Won').reduce((a,d)=>a+d.value,0))}</b></span><em>View CRM →</em></button><button data-launch="finance"><span class="kpi-icon green">${icon('receipt')}</span><span><small>Receivables</small><b>${money(state.invoices.filter(i=>i.status!=='Paid').reduce((a,i)=>a+i.amount,0))}</b></span><em>Open Finance →</em></button><button data-launch="inventory"><span class="kpi-icon orange">${icon('boxes')}</span><span><small>Low stock items</small><b>${state.products.filter(p=>p.stock<15).length}</b></span><em>Review stock →</em></button><button data-launch="services"><span class="kpi-icon purple">${icon('briefcase')}</span><span><small>Active projects</small><b>${state.tasks.length}</b></span><em>View Projects →</em></button></div>
