function toolbar(placeholder='Search records...'){return `<div class="toolbar"><input class="toolbar-search" placeholder="${placeholder}" data-filter-input><button class="btn small" data-icon="filter">Filter</button><div class="toolbar-spacer"></div><div class="view-toggle"><button class="active" data-icon="grid"></button><button data-icon="list"></button></div></div>`}
function sales(){
  const stages=['New','Qualified','Proposal','Won'];
  const cols=stages.map(stage=>{const deals=state.deals.filter(d=>d.stage===stage);return `<section class="kanban-col" data-stage="${stage}"><div class="kanban-head"><strong>${stage}</strong><span>${deals.length}</span></div>${deals.map(d=>`<article class="deal-card" draggable="true" data-id="${d.id}" data-search="${d.company} ${d.title}"><div class="deal-company"><span class="company-dot">${d.company.slice(0,1)}</span>${d.company}</div><h3>${d.title}</h3><span class="deal-value">${money(d.value)}</span><div class="deal-foot"><span class="mini-avatar">${d.owner}</span><span class="probability">${d.prob}% probability</span></div></article>`).join('')}</section>`}).join('');
  return `${header('Sales & CRM','Build relationships, track your pipeline, and turn quotes into revenue.','New opportunity')}${toolbar('Search opportunities...')}<div class="stat-grid"><div class="stat-panel"><span>Pipeline value</span><strong>${money(state.deals.filter(d=>d.stage!=='Won').reduce((a,d)=>a+d.value,0))}</strong><small>↑ 14.2% this month</small></div><div class="stat-panel"><span>Weighted forecast</span><strong>$126,840</strong><small>↑ 8.4% confidence</small></div><div class="stat-panel"><span>Win rate</span><strong>32.8%</strong><small>↑ 3.1 points</small></div><div class="stat-panel"><span>Average cycle</span><strong>18 days</strong><small>2 days faster</small></div></div><div class="kanban" id="dealBoard">${cols}</div>`;
}

